// === CHOo-CHOo TRAIN — MineBench Build ===
// Train runs along +Z. Center X~128. Ground surface Y=2, track on Y=2, rail Y=2.
// All structures rest on ground at Y=2.
var C = 128;
var wheelY = 6; // wheel center; radius 4 -> bottom at y=2 on rail

// ============ GROUND ============
for (var gx = 80; gx <= 176; gx++) {
  for (var gz = 55; gz <= 205; gz++) {
    var gh = Math.floor(Math.sin(gx * 0.05) * 2 + Math.cos(gz * 0.04) * 2 + 3);
    if (gh < 3) gh = 3;
    for (var gy = 0; gy <= 0; gy++) {
      if (gy === gh - 1) box(gx, gy, gz, gx, gy, gz, "grass_block");
      else if (gy > 0) box(gx, gy, gz, gx, gy, gz, "dirt");
      else box(gx, gy, gz, gx, gy, gz, "grass_block");
    }
  }
}

// ============ TRACK ============
// Track bed and sleepers
for (var tkz = 80; tkz <= 185; tkz++) {
  for (var tkx = 123; tkx <= 133; tkx++) {
    block(tkx, 1, tkz, "sand");
    block(tkx, 1, tkz, "oak_log");
  }
}
// Rails — use line() to avoid box() with single-block coords
for (var tkz = 80; tkz <= 185; tkz++) {
  line(123, 2, tkz, 123, 2, tkz, "iron_block");
  line(133, 2, tkz, 133, 2, tkz, "iron_block");
}

// ============ STATION PLATFORM ============
for (var pkz = 100; pkz <= 175; pkz++) {
  for (var px = 88; px <= 117; px++) {
    box(px, 1, pkz, px, 2, pkz, "stone_bricks");
  }
}
for (var pkz = 100; pkz <= 175; pkz++) {
  box(117, 1, pkz, 117, 2, pkz, "cobblestone");
}

// ============ STATION BUILDING ============
for (var sx = 88; sx <= 108; sx++) {
  for (var sz = 68; sz <= 100; sz++) {
    box(sx, 1, sz, sx, 1, sz, "stone_bricks");
  }
}
for (var sx = 88; sx <= 108; sx++) {
  for (var sz = 70; sz <= 98; sz++) {
    for (var sy = 2; sy <= 12; sy++) {
      if (sx === 88 || sx === 108 || sz === 70) {
        box(sx, sy, sz, sx, sy, sz, "stone_bricks");
      }
    }
  }
}
for (var sz = 75; sz <= 95; sz++) {
  if ((sz - 75) % 7 < 3) {
    box(88, 5, sz, 88, 7, sz, "glass");
    box(108, 5, sz, 108, 7, sz, "glass");
  }
}
for (var dx = 98; dx <= 102; dx++) {
  box(dx, 3, 70, dx, 7, 70, "oak_planks");
}
for (var sx = 86; sx <= 110; sx++) {
  for (var sz = 68; sz <= 100; sz++) {
    box(sx, 13, sz, sx, 13, sz, "bricks");
  }
}

// ============ PLATFORM ROOFS ============
var pillarZ = [105, 135, 165];
for (var pi = 0; pi < pillarZ.length; pi++) {
  var pz = pillarZ[pi];
  box(100, 2, pz, 100, 15, pz, "stone_bricks");
  box(104, 2, pz, 104, 15, pz, "stone_bricks");
  for (var roX = 98; roX <= 106; roX++) {
    for (var roZ = pz - 4; roZ <= pz + 4; roZ++) {
      box(roX, 14, roZ, roX, 14, roZ, "bricks");
    }
  }
}

// ============ WHEEL HELPER ============
function wheel(cx, cy, cz, r, thick, type) {
  for (var a = -r; a <= r; a++) {
    for (var b = -r; b <= r; b++) {
      if (a * a + b * b > r * r + 1) continue;
      for (var t = 0; t < thick; t++) {
        block(cx + a, cy + t, cz + b, type);
      }
    }
  }
}

// ============ LOCOMOTIVE ============
var locoFront = 85;
var locoBack = 130;

// Driving wheels (3 pairs, radius 4)
var wz = [90, 105, 120];
for (var wi = 0; wi < wz.length; wi++) {
  wheel(C - 5, wheelY, wz[wi], 4, 2, "iron_block");
  wheel(C + 5, wheelY, wz[wi], 4, 2, "iron_block");
  for (var s = 0; s < 8; s++) {
    var ang = s * Math.PI / 4;
    var sr = 3;
    block(C + Math.round(sr * Math.cos(ang)), wheelY, wz[wi] + Math.round(sr * Math.sin(ang)), "iron_block");
  }
}

// Leading wheels (2 pairs, radius 2)
for (var li = 0; li < 2; li++) {
  var lwz = 87 + li * 5;
  wheel(C - 4, wheelY, lwz, 2, 1, "iron_block");
  wheel(C + 4, wheelY, lwz, 2, 1, "iron_block");
}

// Trailing wheels (2 pairs, radius 2)
for (var ti = 0; ti < 2; ti++) {
  var twz = 125 + ti * 4;
  wheel(C - 3, wheelY, twz, 2, 1, "iron_block");
  wheel(C + 3, wheelY, twz, 2, 1, "iron_block");
}

// Coupling rods
for (var wi = 0; wi < wz.length - 1; wi++) {
  for (var rt = 0; rt < wz[wi + 1] - wz[wi]; rt++) {
    var zz = wz[wi] + rt;
    block(C - 5, wheelY - 1, zz, "iron_block");
    block(C + 5, wheelY - 1, zz, "iron_block");
  }
}

// Frame beams
for (var fz = locoFront; fz <= locoBack; fz++) {
  box(C - 6, wheelY - 1, fz, C - 5, wheelY - 1, fz, "iron_block");
  box(C + 5, wheelY - 1, fz, C + 6, wheelY - 1, fz, "iron_block");
}

// Boiler body (tapered, red)
for (var bz = locoFront + 5; bz <= locoBack - 8; bz++) {
  var br = 7;
  for (var bdy = -br; bdy <= br; bdy++) {
    for (var bdx = -br; bdx <= br; bdx++) {
      if (bdx * bdx + bdy * bdy <= br * br + 1) {
        block(C, 8 + bdy, bz, "red_wool");
      }
    }
  }
}

// Boiler front cap
for (var bfc = -7; bfc <= 7; bfc++) {
  for (var bfr = -7; bfr <= 7; bfr++) {
    if (bfc * bfc + bfr * bfr <= 49) {
      block(C + bfc, 8 + bfr, locoFront + 5, "red_wool");
    }
  }
}

// Boiler bands (iron rings)
for (var bband = locoFront + 10; bband <= locoBack - 10; bband += 6) {
  for (var bbdx = -8; bbdx <= 8; bbdx++) {
    for (var bbdy = -8; bbdy <= 8; bbdy++) {
      if (bbdx * bbdx + bbdy * bbdy <= 64 && bbdx * bbdx + bbdy * bbdy >= 40) {
        block(C + bbdx, 8 + bbdy, bband, "iron_block");
      }
    }
  }
}

// Steam dome (gold) — right side of boiler
for (var sdz = locoFront + 5; sdz <= locoFront + 8; sdz++) {
  for (var sdx = -2; sdx <= 2; sdx++) {
    for (var sdy = 0; sdy <= 3; sdy++) {
      if (sdx * sdx + sdy * sdy <= 9) {
        block(C + sdx + 2, 14 + sdy, sdz, "gold_block");
      }
    }
  }
}

// Sand dome (iron) — left side of boiler
box(C - 5, 16, locoFront + 15, C - 3, 18, locoFront + 18, "iron_block");

// Smokestack — rear of boiler, near cab
var stackZ = locoBack - 10;
for (var sz2 = 0; sz2 <= 6; sz2++) {
  var stackR = 3 - Math.floor(sz2 * 0.3);
  if (stackR < 2) stackR = 2;
  for (var sdx = -stackR; sdx <= stackR; sdx++) {
    for (var sdy = 0; sdy <= 5; sdy++) {
      if (sdx * sdx + sdy * sdy <= stackR * stackR + 1) {
        block(C + sdx, 15 + sz2 + sdy, stackZ + sz2, "black_wool");
      }
    }
  }
}
// Smokestack base plate
box(C - 4, 14, stackZ, C + 4, 14, stackZ + 2, "black_wool");
// Smokestack lip
box(C - 3, 15, stackZ, C + 3, 15, stackZ + 2, "black_wool");

// Cowcatcher — front of locomotive, sits on rail at y=2
for (var cz2 = 0; cz2 <= 4; cz2++) {
  var cw = 3 + cz2;
  for (var cdz = 0; cdz <= cz2; cdz++) {
    box(C - cw, 2 + cdz, locoFront + cz2, C + cw, 2 + cdz, locoFront + cz2, "iron_block");
  }
}
for (var cgz = locoFront; cgz <= locoFront + 4; cgz++) {
  for (var cgy = 0; cgy <= 4; cgy++) {
    block(C, 2 + cgy, cgz, "iron_block");
  }
}

// Headlight — front of locomotive
box(C - 1, 10, locoFront + 3, C + 1, 12, locoFront + 3, "glowstone");
box(C - 2, 9, locoFront + 2, C + 2, 13, locoFront + 2, "iron_block");
box(C - 2, 9, locoFront + 4, C + 2, 13, locoFront + 4, "iron_block");

// Pilot deck — front of locomotive, on rail level
for (var pdz = locoFront; pdz <= locoFront + 6; pdz++) {
  for (var pdx = -4; pdx <= 4; pdx++) {
    box(C + pdx, 4, pdz, C + pdx, 4, pdz, "oak_planks");
  }
}

// ============ CAB ============
var cabZ0 = locoBack - 25;
var cabZ1 = locoBack - 3;
for (var cz3 = cabZ0; cz3 <= cabZ1; cz3++) {
  for (var cy2 = 7; cy2 <= 16; cy2++) {
    box(C - 5, cy2, cz3, C - 5, cy2, cz3, "oak_planks");
    box(C + 5, cy2, cz3, C + 5, cy2, cz3, "oak_planks");
  }
}
for (var cy3 = 7; cy3 <= 16; cy3++) {
  box(C - 5, cy3, cabZ0, C + 5, cy3, cabZ0, "oak_planks");
}
for (var cz4 = cabZ0; cz4 <= cabZ1; cz4++) {
  for (var cdx = -5; cdx <= 5; cdx++) {
    box(C + cdx, 5, cz4, C + cdx, 5, cz4, "oak_planks");
  }
}
for (var cz5 = cabZ0; cz5 <= cabZ1; cz5++) {
  for (var cdx2 = -6; cdx2 <= 6; cdx2++) {
    var roofOff = Math.floor(Math.max(0, 3 - Math.abs(cdx2)) * 0.5);
    box(C + cdx2, 17 + roofOff, cz5, C + cdx2, 17 + roofOff, cz5, "bricks");
  }
}
for (var cwz = cabZ0 + 2; cwz <= cabZ1 - 2; cwz++) {
  box(C - 5, 11, cwz, C - 5, 14, cwz, "glass");
  box(C + 5, 11, cwz, C + 5, 14, cwz, "glass");
}

// ============ TENDER ============
var tenZ0 = locoBack;
var tenZ1 = locoBack + 30;
for (var tndz = tenZ0; tndz <= tenZ1; tndz++) {
  for (var tny = 5; tny <= 11; tny++) {
    for (var tndx = -5; tndx <= 5; tndx++) {
      if (Math.abs(tndx) >= 4 || tny >= 10) {
        block(C + tndx, tny, tndz, "brown_wool");
      } else {
        block(C + tndx, tny, tndz, "oak_planks");
      }
    }
  }
}
for (var tndz2 = tenZ0 + 2; tndz2 <= tenZ1 - 2; tndz2++) {
  for (var tndx2 = -3; tndx2 <= 3; tndx2++) {
    for (var tndy = 0; tndy <= 3; tndy++) {
      var coalH = 3 - Math.floor(Math.abs(tndx2) * 0.5) - tndy;
      if (coalH > 0) {
        block(C + tndx2, 11 + tndy, tndz2, "black_wool");
      }
    }
  }
}
var tenWz = [tenZ0 + 5, tenZ0 + 22];
for (var twi = 0; twi < tenWz.length; twi++) {
  wheel(C - 4, wheelY, tenWz[twi], 3, 1, "iron_block");
  wheel(C + 4, wheelY, tenWz[twi], 3, 1, "iron_block");
}
box(C - 2, 6, tenZ0 - 1, C + 2, 8, tenZ0, "iron_block");

// ============ PASSENGER CAR ============
var carZ0 = tenZ1;
var carZ1 = tenZ1 + 35;
for (var carz = carZ0; carz <= carZ1; carz++) {
  for (var carfdx = -6; carfdx <= 6; carfdx++) {
    box(C + carfdx, 3, carz, C + carfdx, 3, carz, "stone_bricks");
  }
}
for (var carz = carZ0; carz <= carZ1; carz++) {
  for (var carcy = 5; carcy <= 14; carcy++) {
    for (var cardx = -5; cardx <= 5; cardx++) {
      if (carcy === 5 || carcy === 14) {
        block(C + cardx, carcy, carz, "bricks");
      } else if (Math.abs(cardx) === 5) {
        block(C + cardx, carcy, carz, "white_wool");
      } else if (carcy >= 7 && carcy <= 12 && carz >= carZ0 + 3 && carz <= carZ1 - 3 && (carz - carZ0) % 5 < 2) {
        block(C + cardx, carcy, carz, "glass");
      } else {
        block(C + cardx, carcy, carz, "white_wool");
      }
    }
  }
}
for (var carz = carZ0; carz <= carZ1; carz++) {
  for (var cardx4 = -6; cardx4 <= 6; cardx4++) {
    box(C + cardx4, 15, carz, C + cardx4, 15, carz, "bricks");
  }
}
var carWz = [carZ0 + 6, carZ0 + 26];
for (var cwi = 0; cwi < carWz.length; cwi++) {
  wheel(C - 4, wheelY, carWz[cwi], 3, 1, "iron_block");
  wheel(C + 4, wheelY, carWz[cwi], 3, 1, "iron_block");
}
box(C - 2, 6, carZ0 - 1, C + 2, 8, carZ0, "iron_block");

// ============ SMOKE PUFFS — from smokestack at rear ============
var smokeClouds = [
  [C, 12, stackZ - 2, 2],
  [C + 1, 14, stackZ - 3, 2],
  [C - 1, 16, stackZ - 5, 3],
  [C - 2, 18, stackZ - 7, 3],
  [C + 2, 20, stackZ - 8, 3],
  [C - 2, 22, stackZ - 10, 3],
  [C + 1, 25, stackZ - 12, 4],
  [C - 1, 27, stackZ - 14, 4],
  [C, 30, stackZ - 16, 4],
  [C + 2, 32, stackZ - 18, 5],
  [C - 1, 35, stackZ - 20, 5]
];
for (var si = 0; si < smokeClouds.length; si++) {
  var sc = smokeClouds[si];
  for (var sdx3 = -sc[3]; sdx3 <= sc[3]; sdx3++) {
    for (var sdy2 = -sc[3]; sdy2 <= sc[3]; sdy2++) {
      for (var sdzV = -sc[3]; sdzV <= sc[3]; sdzV++) {
        if (sdx3 * sdx3 + sdy2 * sdy2 + sdzV * sdzV <= sc[3] * sc[3] + 1) {
          block(sc[0] + sdx3, sc[1] + sdy2, sc[2] + sdzV, "white_wool");
        }
      }
    }
  }
}

// ============ TREES ============
function tree(tx, ty, tz) {
  for (var tk = ty; tk <= ty + 6; tk++) {
    box(tx, tk, tz, tx, tk, tz, "oak_log");
  }
  for (var tky = -3; tky <= 2; tky++) {
    for (var tkx = -3; tkx <= 3; tkx++) {
      for (var tkz = -3; tkz <= 3; tkz++) {
        if (tkx * tkx + tky * tky + tkz * tkz <= 12) {
          box(tx + tkx, ty + 3 + tky, tz + tkz, tx + tkx, ty + 3 + tky, tz + tkz, "oak_leaves");
        }
      }
    }
  }
}
tree(90, 3, 60);
tree(150, 3, 70);
tree(85, 3, 190);
tree(155, 3, 185);
tree(75, 4, 130);

// ============ BENCHES ============
for (var bz = 110; bz <= 116; bz++) {
  box(110, 5, bz, 110, 5, bz, "oak_planks");
}
for (var bz2 = 140; bz2 <= 146; bz2++) {
  box(110, 5, bz2, 110, 5, bz2, "oak_planks");
}

// ============ FLAG ============
box(98, 18, 84, 98, 23, 84, "oak_log");
box(99, 18, 84, 102, 18, 84, "red_wool");

// ============ LAMP POST ============
box(115, 5, 130, 115, 15, 130, "iron_block");
box(114, 16, 130, 116, 16, 130, "glowstone");
box(114, 17, 130, 116, 17, 130, "iron_block");

// ============ CHIMNEY SMOKE WISPS — from smokestack ============
for (var wsi = 0; wsi < 15; wsi++) {
  var wobble = Math.floor(wsi * 1.3);
  block(C + wobble, 10 + Math.floor(wsi * 0.3), stackZ - 1 - Math.floor(wsi * 0.5), "white_wool");
}
